{
  "name": "@maximtop/opencode-session-namer",
  "version": "0.4.0",
  "description": "opencode plugin that names sessions from PR links and project directories: [project] AG-123 Review pull/1226 <PR title>",
  "type": "module",
  "main": "src/index.ts",
  "files": [
    "src",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "lint": "eslint .",
    "type-check": "tsc --noEmit",
    "test": "vitest run"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "session",
    "title"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/maximtop/opencode-session-namer.git"
  },
  "bugs": "https://github.com/maximtop/opencode-session-namer/issues",
  "homepage": "https://github.com/maximtop/opencode-session-namer#readme",
  "peerDependencies": {
    "@opencode-ai/plugin": "*",
    "@opencode/plugin": "*"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "1.18.27",
    "@types/node": "^24.9.1",
    "@typescript-eslint/eslint-plugin": "^7.18.0",
    "@typescript-eslint/parser": "^7.18.0",
    "eslint": "^8.57.1",
    "eslint-config-airbnb-base": "^15.0.0",
    "eslint-config-airbnb-typescript": "^18.0.0",
    "eslint-import-resolver-typescript": "^4.4.4",
    "eslint-plugin-import": "^2.31.0",
    "eslint-plugin-jsdoc": "^60.6.0",
    "typescript": "^5.8.3",
    "vitest": "^4.0.6",
    "@opencode/plugin": "2.0.14"
  },
  "dependencies": {
    "zod": "4.1.8"
  },
  "peerDependenciesMeta": {
    "@opencode-ai/plugin": {
      "optional": true
    },
    "@opencode/plugin": {
      "optional": true
    }
  },
  "exports": {
    ".": "./src/index.ts",
    "./server": "./src/server.ts"
  }
}
